package com.studenttong.mobile;
import android.net.Uri;import android.location.Location;import android.os.SystemClock;import java.util.*;import org.json.*;
public final class SignLogic {
 public static String digits(String s)throws Exception{if(s==null||!s.matches("[0-9]+"))throw new Exception("请先在平台中打开课程或活动页");return s;}
 public static JSONObject course(String url)throws Exception{if(!Store.trusted(url,"chaoxing"))throw new Exception("请使用学习通课程或活动页链接");Uri u=Uri.parse(url);String course=first(u,"courseId","courseid"),clazz=first(u,"classId","classid","clazzid","clazzId","jclassId");return new JSONObject().put("courseId",digits(course)).put("classId",digits(clazz));}
 static String first(Uri u,String...keys){for(String k:keys){String v=u.getQueryParameter(k);if(v!=null&&!v.isEmpty())return v;}return null;}
 public static String url(String active,String course,String clazz)throws Exception{return Uri.parse("https://mobilelearn.chaoxing.com/newsign/preSign").buildUpon().appendQueryParameter("activePrimaryId",digits(active)).appendQueryParameter("courseId",digits(course)).appendQueryParameter("classId",digits(clazz)).appendQueryParameter("general","1").appendQueryParameter("sys","1").appendQueryParameter("ls","1").appendQueryParameter("appType","15").build().toString();}
 public static boolean matches(String url,JSONObject entry){try{Uri u=Uri.parse(url);return Store.trusted(url,"chaoxing")&&"mobilelearn.chaoxing.com".equals(u.getHost())&&"/newsign/preSign".equals(u.getPath())&&entry.optString("id").equals(u.getQueryParameter("activePrimaryId"))&&entry.optString("courseId").equals(u.getQueryParameter("courseId"))&&entry.optString("classId").equals(u.getQueryParameter("classId"));}catch(Exception e){return false;}}
 public static List<JSONObject> activities(JSONObject response,JSONObject course)throws Exception{if(response.optInt("result")!=1&&!response.optBoolean("result"))throw new Exception("平台未返回活动列表，请先登录当前账号");JSONArray list=response.optJSONObject("data")==null?null:response.optJSONObject("data").optJSONArray("activeList");if(list==null)throw new Exception("活动列表结构未识别");List<JSONObject> out=new ArrayList<>();for(int i=0;i<list.length();i++){JSONObject r=list.getJSONObject(i);if(r.optInt("activeType")!=2)continue;String id=digits(r.optString("id")),other=r.optString("otherId");JSONObject a=new JSONObject().put("id",id).put("title",r.optString("nameOne","签到")).put("kind","4".equals(other)?"location":"0".equals(other)?"normal":"manual").put("ongoing",r.optInt("status")==1).put("courseId",course.getString("courseId")).put("classId",course.getString("classId"));out.add(a);}return out;}
 public static String verdict(String reply,String body){reply=reply==null?"":reply.trim();body=body==null?"":body;if(Arrays.asList("success","success2").contains(reply)||reply.contains("您已签到过了")||body.matches("(?s).*(恭喜你已完成签到|您已签到过了|您已签到|签到成功).*"))return "completed";if("validate".equals(reply)||reply.contains("[face]")||body.matches("(?s).*(需要.*验证|滑块验证|人脸验证|请用学习通客户端).*"))return "verification";if(reply.contains("范围")||reply.contains("位置")&&reply.contains("失败"))return "rejected";if(body.matches("(?s).*(签到已结束|活动已结束|不在签到时间).*"))return "ended";return reply.isEmpty()?"pending":"uncertain";}
 public static boolean fresh(Location l,long now){return l!=null&&Double.isFinite(l.getLatitude())&&Double.isFinite(l.getLongitude())&&Math.abs(l.getLatitude())<=90&&Math.abs(l.getLongitude())<=180&&l.hasAccuracy()&&l.getAccuracy()>0&&l.getAccuracy()<=2000&&l.getElapsedRealtimeNanos()>0&&now>=l.getElapsedRealtimeNanos()&&now-l.getElapsedRealtimeNanos()<=120000000000L;}
 // WGS84 -> GCJ02 -> BD09. Formula port of wandergis/coordtransform (MIT, see bundled license).
 public static double[] bd09(double lon,double lat){if(!Double.isFinite(lon)||!Double.isFinite(lat)||Math.abs(lon)>180||Math.abs(lat)>90)throw new IllegalArgumentException("无效坐标");double x=lon,y=lat;if(lon>=73.66&&lon<=135.05&&lat>=3.86&&lat<=53.55){double dl=latitude(lon-105,lat-35),dn=longitude(lon-105,lat-35),rad=lat/180*Math.PI,m=Math.sin(rad);m=1-0.00669342162296594323*m*m;double sq=Math.sqrt(m);dl=dl*180/((6378245*(1-0.00669342162296594323))/(m*sq)*Math.PI);dn=dn*180/(6378245/sq*Math.cos(rad)*Math.PI);x+=dn;y+=dl;}double xp=Math.PI*3000/180,z=Math.sqrt(x*x+y*y)+0.00002*Math.sin(y*xp),theta=Math.atan2(y,x)+0.000003*Math.cos(x*xp);return new double[]{z*Math.cos(theta)+0.0065,z*Math.sin(theta)+0.006};}
 static double latitude(double x,double y){double r=-100+2*x+3*y+.2*y*y+.1*x*y+.2*Math.sqrt(Math.abs(x));r+=(20*Math.sin(6*x*Math.PI)+20*Math.sin(2*x*Math.PI))*2/3;r+=(20*Math.sin(y*Math.PI)+40*Math.sin(y/3*Math.PI))*2/3;r+=(160*Math.sin(y/12*Math.PI)+320*Math.sin(y*Math.PI/30))*2/3;return r;}
 static double longitude(double x,double y){double r=300+x+2*y+.1*x*x+.1*x*y+.1*Math.sqrt(Math.abs(x));r+=(20*Math.sin(6*x*Math.PI)+20*Math.sin(2*x*Math.PI))*2/3;r+=(20*Math.sin(x*Math.PI)+40*Math.sin(x/3*Math.PI))*2/3;r+=(150*Math.sin(x/12*Math.PI)+300*Math.sin(x/30*Math.PI))*2/3;return r;}
}
